8.query:
timeseries cpu = avg(dt.host.cpu.usage), by:{dt.entity.host}, from:now()-24h, interval:1h
| fieldsAdd host_id = dt.entity.host
| lookup [
  fetch logs, from:now()-24h
  | filter isNotNull(dt.entity.host)
  | summarize log_count = count(), by:{host_id = dt.entity.host}
], sourceField:host_id, lookupField:host_id, fields:{log_count}
| lookup [
  fetch spans, from:now()-24h
  | filter isNotNull(dt.entity.host)
  | summarize span_count = count(), by:{host_id = dt.entity.host}
], sourceField:host_id, lookupField:host_id, fields:{span_count}
| summarize `Weak Signals` = countIf(coalesce(log_count, 0) == 0 or coalesce(span_count, 0) == 0)

16.query:
timeseries {
  cpu = avg(dt.host.cpu.usage),
  disk = avg(dt.host.disk.used.percent),
  net = avg(dt.host.net.nic.bytes_rx)
}, by:{dt.entity.host}, from:now()-24h, interval:1h
| fieldsAdd host = entityName(dt.entity.host)
| fieldsAdd host_id = dt.entity.host
| fieldsAdd HostMetrics_now = if(isNotNull(arrayAvg(cpu)), "Y", else:"N")
| fieldsAdd Disk_now = if(isNotNull(arrayAvg(disk)), "Y", else:"N")
| fieldsAdd Network_now = if(isNotNull(arrayAvg(net)), "Y", else:"N")
| lookup [
  timeseries pcpu = avg(dt.process.cpu.usage), by:{dt.entity.host}, from:now()-24h, interval:1h
  | fieldsAdd Process_now = "Y"
  | fields host_id = dt.entity.host, Process_now
], sourceField:host_id, lookupField:host_id, fields:{Process_now}
| lookup [
  fetch logs, from:now()-24h
  | filter isNotNull(dt.entity.host)
  | summarize log_count = count(), by:{host_id = dt.entity.host}
], sourceField:host_id, lookupField:host_id, fields:{log_count}
| lookup [
  fetch spans, from:now()-24h
  | filter isNotNull(dt.entity.host)
  | summarize span_count = count(), by:{host_id = dt.entity.host}
], sourceField:host_id, lookupField:host_id, fields:{span_count}
| lookup [
  fetch dt.entity.service
  | fieldsAdd runs_on
  | expand dt.entity.host = runs_on[dt.entity.host]
  | filter isNotNull(dt.entity.host)
  | summarize service_count = count(), by:{host_id = dt.entity.host}
], sourceField:host_id, lookupField:host_id, fields:{service_count}
| lookup [
  timeseries {
    cpu7 = avg(dt.host.cpu.usage),
    disk7 = avg(dt.host.disk.used.percent),
    net7 = avg(dt.host.net.nic.bytes_rx)
  }, by:{dt.entity.host}, from:now()-7d-24h, to:now()-7d, interval:1h
  | fieldsAdd HostMetrics_7d = if(isNotNull(arrayAvg(cpu7)), "Y", else:"N")
  | fieldsAdd Disk_7d = if(isNotNull(arrayAvg(disk7)), "Y", else:"N")
  | fieldsAdd Network_7d = if(isNotNull(arrayAvg(net7)), "Y", else:"N")
  | fields host_id = dt.entity.host, HostMetrics_7d, Disk_7d, Network_7d
], sourceField:host_id, lookupField:host_id, fields:{HostMetrics_7d, Disk_7d, Network_7d}
| lookup [
  fetch logs, from:now()-7d-24h, to:now()-7d
  | filter isNotNull(dt.entity.host)
  | summarize log_count_7d = count(), by:{host_id = dt.entity.host}
], sourceField:host_id, lookupField:host_id, fields:{log_count_7d}
| lookup [
  fetch spans, from:now()-7d-24h, to:now()-7d
  | filter isNotNull(dt.entity.host)
  | summarize span_count_7d = count(), by:{host_id = dt.entity.host}
], sourceField:host_id, lookupField:host_id, fields:{span_count_7d}
| fieldsAdd
    Process_now = coalesce(Process_now, "N"),
    Logs_now = if(coalesce(log_count, 0) > 0, "Y", else:"N"),
    Traces_now = if(coalesce(span_count, 0) > 0, "Y", else:"N"),
    Services_now = if(coalesce(service_count, 0) > 0, "Y", else:"N"),
    Frontends_now = "n/a",
    HostMetrics_7d = coalesce(HostMetrics_7d, "N"),
    Disk_7d = coalesce(Disk_7d, "N"),
    Network_7d = coalesce(Network_7d, "N"),
    Logs_7d = if(coalesce(log_count_7d, 0) > 0, "Y", else:"N"),
    Traces_7d = if(coalesce(span_count_7d, 0) > 0, "Y", else:"N")
| fields host, HostMetrics_now, Disk_now, Network_now, Process_now, Logs_now, Traces_now, Services_now, Frontends_now, HostMetrics_7d, Disk_7d, Network_7d, Logs_7d, Traces_7d
| sort host asc
